#define R(p, a, r) mix(a * dot(p, a), p, cos(r)) + sin(r) * cross(p, a)
#define H(h) (cos((h) * 6.3 + vec3(0, 23, 21)) * 0.5 + 0.5)

void mainImage(out vec4 O, vec2 C) {
    O = vec4(0.0);
    vec3 p, r = iResolution;
    vec3 d = normalize(vec3((C * 2.0 - r.xy) / r.y, 1.0)); // Ray direction

    for (float i = 0.0, a, s, e, g = 0.0;
         ++i < 110.0;
         O.xyz += mix(vec3(1.0), H(g * 0.1), sin(0.8)) * 1.0 / e / 8e3) {

        p = g * d;
        p.z += iTime * 6.5; // Dynamic motion along the z-axis
        a = 10.0;
        p = mod(p - a, a * 2.0) - a; // Looping geometry
        s = 6.0;

        // Recursive fractal loop
        for (int j = 0; j++ < 8;) {
            p = 0.3 - abs(p); // Recursive inversion

            // Axis permutation for symmetry
            p.x < p.z ? p = p.zyx : p;
            p.z < p.y ? p = p.xzy : p;

            // Recursive scaling and offsets
            s *= e = 1.4 + sin(iTime * 0.234) * 0.1;
            p = abs(p) * e -
                vec3(
                    5.0 + tan(iTime * 0.3 + 0.5 * tan(iTime * 0.3)) * 3.0,
                    120.0,
                    8.0 + cos(iTime * 0.2) * 5.0
                );
        }
        g += e = length(p.yz) / s; // Accumulate glow effect
    }

    // Add glow and color adjustments
    O.xyz = pow(O.xyz, vec3(0.8)); // Smooth glow
    O.xyz += 0.1 * sin(iTime * 2.0 + O.xyz * 10.0); // Subtle color pulsations
    O.xyz *= 1.5; // Amplify brightness for vibrancy

    O.w = 1.0; // Full opacity
}
